ws = wb['Sheet1']

# Build lookup dictionaries (case-insensitive for list1 based on expected results)
list1 = {}
for row in range(2, 14):
    name = ws.cell(row=row, column=7).value  # G column
    id_val = ws.cell(row=row, column=8).value  # H column
    if name is not None and id_val is not None:
        list1[str(name).strip().lower()] = id_val

list2 = {}
for row in range(2, 7):
    name = ws.cell(row=row, column=10).value  # J column
    id_val = ws.cell(row=row, column=11).value  # K column
    if name is not None and id_val is not None:
        list2[str(name).strip().lower()] = id_val

print(f"List1: {list1}")
print(f"List2: {list2}")

# Fill D2:D7 based on conditions
for row in range(2, 8):
    b_val = ws.cell(row=row, column=2).value  # B column
    c_val = ws.cell(row=row, column=3).value  # C column

    b_str = str(b_val).strip() if b_val is not None else ''
    c_str = str(c_val).strip() if c_val is not None else ''

    if b_str == '' and c_str == '':
        # Both blank -> D blank
        result = None
    elif b_str.lower() in list1:
        # B exists in list1 -> ID from list1
        result = list1[b_str.lower()]
    elif b_str == '':
        # B blank, check C in list2
        if c_str.lower() in list2:
            result = list2[c_str.lower()]
        else:
            result = 2500
    else:
        # B not in list1, check C in list2
        if c_str.lower() in list2:
            result = list2[c_str.lower()]
        else:
            result = 2500

    ws.cell(row=row, column=4).value = result
    print(f"Row {row}: B={b_val!r}, C={c_val!r} -> D={result!r}")

wb.save(out_path)
print("Saved.")
